from 写入第二遍 import add
add('16_002',7,'16:9，从青后肩看远处烟尘，青在右前景，模糊武士人影在左后；相机固定，不随发声改看青正脸，焦点从她肩部移向尘中的人影后停住。','青的发束从肩外落下，她原本扬起的嘴角不再保持，头部转正看向烟尘中的武士；远处影子把右臂收向左身，传来入鞘轻响，再抬起左臂将带鞘刀送回肩后，背带随肩线滑回。人影直起开始向前走，青的右肩不自觉绷高，手还停在腰侧。','米灰尘层在两人之间从浓到薄分开，远处铅蓝云天显露，石铺地只在下缘窄窄入画。','烟囱后侧开阔天空的冷白光透过薄尘，远处人影渐从暗灰中分离。','尘中一声短促收刀合鞘，背带与衣料摩擦，随后脚步不急不慢靠近；近处青的呼吸稍重。',japanese=['柔軟性、十点。','持久力、十点。','判断力も十点。'],tone='武士在远处逐项评点，气息没有受挫；声音不配给青的口型。',phase='reaction',kind='mixed',node={'武士.刀':'肩后鞘内','武士.阶段':'收刀后从尘中走近','青.阶段':'停稳后注视武士'},pcard={'opening':'青落地后的短暂自信等着对手结果。','beats':['听到仍从容的声音，头正过来','右肩绷高、手停腰侧；远处人影收刀走近'],'coupling':'武士无碍的声音消掉青的得手感。','landing':'青已正视仍能行动的对手。'})
add('16_003',13,'16:9，略低的全身景，武士从米灰尘层向前走；相机后退跟随，起幅见肩后刀柄与破边外衣，随后缓慢下摇至迈步与脚边尘浪，末段上摇落回头肩中景。','武士一步步走出烟尘，双手已经空下，肩后刀柄随步伐轻晃，破外衣从尘层中拖出后又向两侧摊开。他说前半句时头略偏，狭窄眼缝始终指向画外的青；说到后半句，前脚稳稳落下，偏着的头慢慢摆正，胸口毫不吃力地抬起，最后在双方尚有距离处停步。','米灰尘浪从膝旁退向身后，灰绿石铺地在下摇时扩大，上摇后只留低处一带；后方铅蓝天空和模糊残墙轮廓。','同一开阔天空冷白柔光从武士后上侧照入，尘中亮度逐渐恢复。','鞋底压石、碎粒轻滚与破衣拖风交替，呼吸平稳；尘层仍有沉闷余响。',japanese=['見事だ。セックスに必要な要素は、どれも満点だ。','だが、お前には戦いの才能がない。'],tone='先像称赞，再平静压下结论，后句不靠吼叫。',phase='process',kind='mixed',node={'武士.阶段':'走出烟尘停下','双方.距离':'空地相隔对峙'},pcard={'opening':'武士行动和发声都无明显伤效。','beats':['从烟尘里走出，偏头评点','前脚稳落、头摆正，用停步压住结论'],'coupling':'展示从容的身体状态，使青的判断被迫改变。','landing':'停在可再交手的距离，主动权仍在他手里。'})
add('17_001',20,'16:9，青正面中近景，额头到腰上入画，前景一只抬起又松垂的手在左侧；固定机位留足肩背，末段只推到胸上近景，不切掉汗、半垂眼与张嘴回击。','青半压眼睑，眉头挤紧，带擦痕的右手抬到身前后松垂，手指细颤；她挺起胸肩朝画外武士顶回第一句，嘴角露出咬牙的折形。提到自己时，脸侧红色加深，先前顶出的下巴缩回一点，眼睛仍不肯避开对手，声音短暂结巴。外在话说完，她嘴唇抿住，肩背随一口较重呼气落下，眼睛越过自己的手再次量着武士，半垂的眼形变得更紧，汗顺额角滑下。','远处石铺地与薄尘被压成浅灰绿、冷米灰两层虚化色面；上边是冷灰天空。','开阔天空冷白柔光从青侧上方照来，脸侧血色保持局部，不改变衣装固有色。','近处呼吸稍乱、手部衣料轻摩擦；对面脚步已经停下，余尘轻落。',japanese=['その口の悪さは、見た目のいやらしさと同じくらいね。','わ、私なんて、まだ一緒にそういうことをする相手もいないのに。','信じられない。あの一発を食らったのに、まだぴんぴんしてる。'],tone='第一句带恼火顶回；第二句羞恼结巴；最后为内心警惕评估，不做口型。',phase='reaction',kind='mixed',node={'青.阶段':'嘴硬回击并重新评估伤效'},pcard={'opening':'青有汗有擦伤，得手后的放松被对手无碍打破。','beats':['半垂眼、松垂手与挺胸回嘴形成反差','说到自己时羞恼、下巴收回却仍盯对手','闭嘴呼气，重新量对手的身体状态'],'coupling':'外在反驳与内心担忧并行，听者不能响应她的内心。','landing':'身体疲态与警惕都持续，态度尚不服输。'})
